  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects amount exceeding invoice total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    number: 'INV-2026-0001',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
  };

  const result = createCreditNote(invoice, { amount: 9000, reason: 'Partial refund', date: '2026-10-08' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote allows amount equal to invoice total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    number: 'INV-2026-0001',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
  };

  const result = createCreditNote(invoice, { amount: 8500, reason: 'Full refund', date: '2026-10-08' }, []);

  assert.equal(result.ok, true);
});

test('createCreditNote respects invoice VAT in total calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    number: 'INV-2026-0001',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  // Invoice total should be 8500 + VAT = 8500 + 1785 = 10285
  const result = createCreditNote(invoice, { amount: 10286, reason: 'Over limit', date: '2026-10-08' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote respects invoice discount in total calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    number: 'INV-2026-0001',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 10 }],
  };

  // Invoice total should be 10000 - 1000 = 9000
  const result = createCreditNote(invoice, { amount: 9001, reason: 'Over limit', date: '2026-10-08' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

