  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0003');
});

test('createCreditNote resets counter for new year', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    number: 'INV-2026-0001',
    status: 'issued',
